-- Confere:
SELECT numero, local,
       CASE WHEN foto_antes IS NOT NULL OR foto_antes_path IS NOT NULL
            THEN 'com foto' ELSE 'SEM FOTO' END AS situacao
  FROM public.conformidades
 WHERE empresa_id = '75447c33-0960-46db-ba59-00327575fe44'
 ORDER BY numero;
